CREATE TABLE IF NOT EXISTS organizations(id text PRIMARY KEY,name text NOT NULL);
CREATE TABLE IF NOT EXISTS memberships(id text PRIMARY KEY,org_id text REFERENCES organizations(id),user_id text NOT NULL,role text NOT NULL);
CREATE TABLE IF NOT EXISTS events(id text PRIMARY KEY,org_id text REFERENCES organizations(id),name text NOT NULL,location text NOT NULL,date text NOT NULL,status text NOT NULL DEFAULT 'Active');
CREATE TABLE IF NOT EXISTS zones(id text PRIMARY KEY,org_id text REFERENCES organizations(id),event_id text REFERENCES events(id),name text NOT NULL,x double precision NOT NULL,y double precision NOT NULL);
CREATE TABLE IF NOT EXISTS partners(id text PRIMARY KEY,org_id text REFERENCES organizations(id),name text NOT NULL,materials jsonb NOT NULL,capacity double precision NOT NULL CHECK(capacity>0),available boolean NOT NULL,distance double precision NOT NULL);
CREATE TABLE IF NOT EXISTS batches(id text PRIMARY KEY,org_id text REFERENCES organizations(id),event_id text REFERENCES events(id),zone_id text REFERENCES zones(id),material text NOT NULL,weight double precision NOT NULL CHECK(weight>0),status text NOT NULL,partner_id text REFERENCES partners(id),accepted double precision NOT NULL DEFAULT 0 CHECK(accepted>=0),rejected double precision NOT NULL DEFAULT 0 CHECK(rejected>=0),evidence text,notes text NOT NULL DEFAULT '',revision integer NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS captures(id text PRIMARY KEY,org_id text REFERENCES organizations(id),event_id text REFERENCES events(id),zone_id text REFERENCES zones(id),batch_id text REFERENCES batches(id),material text NOT NULL,weight double precision NOT NULL CHECK(weight>0),provenance text NOT NULL,quantity integer NOT NULL CHECK(quantity>0),notes text NOT NULL DEFAULT '',evidence text,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS custody_events(id text PRIMARY KEY,org_id text REFERENCES organizations(id),batch_id text REFERENCES batches(id),action text NOT NULL,role text NOT NULL,details jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS receipts(id text PRIMARY KEY,org_id text REFERENCES organizations(id),batch_id text UNIQUE REFERENCES batches(id),accepted double precision NOT NULL,rejected double precision NOT NULL,evidence text NOT NULL,notes text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS passports(id text PRIMARY KEY,org_id text REFERENCES organizations(id),batch_id text REFERENCES batches(id),revision integer NOT NULL,payload jsonb NOT NULL,hash text NOT NULL,signature text NOT NULL,key_id text NOT NULL,revoked boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(batch_id,revision));
CREATE TABLE IF NOT EXISTS signing_keys(id text PRIMARY KEY,public_key jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS idempotency_records(org_id text NOT NULL,key text NOT NULL,request_hash text NOT NULL,response jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(org_id,key));
CREATE TABLE IF NOT EXISTS media(id text PRIMARY KEY,org_id text REFERENCES organizations(id),mime text NOT NULL,path text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS audit_events(id text PRIMARY KEY,org_id text REFERENCES organizations(id),role text NOT NULL,action text NOT NULL,details jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS batches_scope ON batches(org_id,event_id,status);
CREATE INDEX IF NOT EXISTS captures_scope ON captures(org_id,event_id);
CREATE OR REPLACE FUNCTION prevent_custody_mutation() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'Custody history is append-only'; END $$;
DROP TRIGGER IF EXISTS immutable_custody ON custody_events;
CREATE TRIGGER immutable_custody BEFORE UPDATE OR DELETE ON custody_events FOR EACH ROW EXECUTE FUNCTION prevent_custody_mutation();
